context_title:
domain Bitwise {
  function wrap_add(a: Int, b: Int): Int
  function wrap_mul(a: Int, b: Int): Int
  function xor(a: Int, b: Int): Int
  function and(a: Int, b: Int): Int
  function or(a: Int, b: Int): Int
  function popcount(a: Int): Int
  function lsh(a: Int, b: Int): Int

  axiom wrap_add_axiom {
    forall a: Int, b: Int :: { wrap_add(a, b) }
      wrap_add(a, b) == (a + b) % (2^64)
  }
  axiom wrap_mul_axiom {
    forall a: Int, b: Int :: { wrap_mul(a, b) }
      wrap_mul(a, b) == (a * b) % (2^64)
  }
  axiom xor_axiom {
    forall a: Int, b: Int :: { xor(a, b) }
      xor(a, b) >= 0
  }
  axiom popcount_axiom {
    forall a: Int :: { popcount(a) }
      popcount(a) >= 0 && popcount(a) <= 64
  }
}

domain FloatMath {
  function clamp(val: Real, min_val: Real, max_val: Real): Real
  function sqrt(val: Real): Real
  function is_nan(val: Real): Bool
  function is_inf(val: Real): Bool
  function inf_val(): Real

  axiom clamp_axiom {
    forall val: Real, min_val: Real, max_val: Real :: { clamp(val, min_val, max_val) }
      min_val <= max_val ==>
      (val < min_val ==> clamp(val, min_val, max_val) == min_val) &&
      (val > max_val ==> clamp(val, min_val, max_val) == max_val) &&
      (min_val <= val && val <= max_val ==> clamp(val, min_val, max_val) == val)
  }
  axiom sqrt_axiom {
    forall val: Real :: { sqrt(val) }
      val >= 0.0 ==> sqrt(val) >= 0.0 && sqrt(val) * sqrt(val) == val
  }
  axiom nan_inf_axiom {
    forall val: Real :: { is_nan(val), is_inf(val) }
      is_nan(val) ==> !is_inf(val)
  }
}

domain Hashing {
  function stable_hash(data: Seq[Int], seed: Int): Int
  axiom stable_hash_range {
    forall data: Seq[Int], seed: Int :: { stable_hash(data, seed) }
      stable_hash(data, seed) >= 0
  }
}

class RankedSegment {
  var tokens: Seq[Int]
  var score: Real
  var position: Int
  var anchor: Bool

  method init(toks: Seq[Int], sc: Real, pos: Int, anc: Bool)
    modifies this.tokens, this.score, this.position, this.anchor
    ensures acc(this.tokens, write) && acc(this.score, write) && acc(this.position, write) && acc(this.anchor, write)
    ensures this.tokens == toks && this.score == sc && this.position == pos && this.anchor == anc
  {
    this.tokens := toks;
    this.score := sc;
    this.position := pos;
    this.anchor := anc;
  }

  method deinit()
    requires acc(this.tokens, write)
    ensures true
  {
    this.tokens := Seq[Int] {};
  }
}

class BitSet {
  var bits: Seq[Int]

  method init(cap: Int)
    modifies this.bits
    ensures acc(this.bits, write) && |this.bits| == (cap / 64 + 1)
  {
    this.bits := Seq[Int] { 0, 0, 0 };
  }

  method set(index: Int)
    requires acc(this.bits, write)
    requires 0 <= index < |this.bits| * 64
    modifies this.bits
  {
    var word_idx: Int := index / 64;
    var bit_idx: Int := index % 64;
    var mask: Int := Bitwise.lsh(1, bit_idx);
    this.bits := this.bits[word_idx := Bitwise.or(this.bits[word_idx], mask)];
  }

  method deinit()
    requires acc(this.bits, write)
    ensures true
  {
    this.bits := Seq[Int] {};
  }
}

class Tensor {
  var data: Seq[Real]
  var shape: Seq[Int]

  method init(dims: Seq[Int])
    modifies this.data, this.shape
    ensures acc(this.data, write) && acc(this.shape, write)
    ensures this.shape == dims
    ensures |this.data| > 0
  {
    this.shape := dims;
    this.data := Seq[Real] { 0.0, 0.0, 0.0 };
  }

  method deinit()
    requires acc(this.data, write) && acc(this.shape, write)
    ensures true
  {
    this.data := Seq[Real] {};
    this.shape := Seq[Int] {};
  }
}

class SSI {
  var segments: Seq[RankedSegment]

  method init()
    modifies this.segments
    ensures acc(this.segments, write) && |this.segments| == 0
  {
    this.segments := Seq[RankedSegment] {};
  }

  method addSequence(toks: Seq[Int], pos: Int, anc: Bool)
    requires acc(this.segments, write)
    modifies this.segments
    ensures acc(this.segments, write)
  {
    var seg: RankedSegment;
    new(seg);
    seg.init(toks, 0.0, pos, anc);
    this.segments := this.segments + Seq[RankedSegment] { seg };
  }

  method deinit()
    requires acc(this.segments, write)
    ensures true
  {
  }

  method getSegment(h: Int) returns (s: RankedSegment)
    requires acc(this.segments, read)
    ensures s == null || (acc(s.tokens, read) && acc(s.score, read) && acc(s.position, read) && acc(s.anchor, read))
  {
    if (|this.segments| > 0) {
      s := this.segments[0];
    } else {
      s := null;
    }
  }

  method retrieveTopK(query: Seq[Int], k: Int) returns (candidates: Seq[RankedSegment])
    requires acc(this.segments, read)
    ensures |candidates| >= 0
  {
    candidates := Seq[RankedSegment] {};
  }
}

class Allocator {
  var dummy: Int

  method init()
    ensures acc(this.dummy, write)
  {
    this.dummy := 0;
  }

  method alloc_f32(len: Int) returns (res: Seq[Real])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[Real](len, 0.0);
  }

  method alloc_u64(len: Int) returns (res: Seq[Int])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[Int](len, 0);
  }

  method alloc_bool(len: Int) returns (res: Seq[Bool])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[Bool](len, false);
  }

  method alloc_int(len: Int) returns (res: Seq[Int])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[Int](len, 0);
  }

  method alloc_Seq_Int(len: Int) returns (res: Seq[Seq[Int]])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[Seq[Int]](len, Seq[Int] {});
  }

  method alloc_RankedSegment(len: Int) returns (res: Seq[RankedSegment])
    requires len >= 0
    ensures |res| == len
  {
    res := Seq[RankedSegment](len, null);
  }

  method free_seq_int(s: Seq[Int])
  requires true
  {
  }

  method free_seq_real(s: Seq[Real])
  requires true
  {
  }

  method free_seq_bool(s: Seq[Bool])
  requires true
  {
  }

  method free_seq_seq_int(s: Seq[Seq[Int]])
  requires true
  {
  }

  method dupe_u32(src: Seq[Int]) returns (res: Seq[Int])
  ensures |res| == |src|
  {
    res := src;
  }
}

class Reader {
  var data: Seq[Int]
  var pos: Int

  method init(d: Seq[Int])
    modifies this.data, this.pos
    ensures acc(this.data, write) && acc(this.pos, write)
    ensures this.data == d && this.pos == 0
  {
    this.data := d;
    this.pos := 0;
  }

  method read(buf_len: Int) returns (bytes: Seq[Int])
    requires acc(this.data, read) && acc(this.pos, write)
    modifies this.pos
    ensures bytes == Seq[Int] {} || |bytes| > 0
  {
    if (this.pos < |this.data|) {
      bytes := Seq[Int] { this.data[this.pos] };
      this.pos := this.pos + 1;
    } else {
      bytes := Seq[Int] {};
    }
  }
}

class Ranker {
  var ngram_weights: Seq[Real]
  var lsh_hash_params: Seq[Int]
  var num_hash_functions: Int
  var num_ngrams: Int
  var seed: Int
  var allocator: Allocator

  method init(allocator: Allocator, num_ngrams: Int, num_hash_funcs: Int, seed: Int) returns (res: Ranker)
    requires num_ngrams > 0
    requires num_hash_funcs > 0
    requires acc(allocator.dummy, write)
    modifies allocator
    ensures acc(res.ngram_weights, write) && acc(res.lsh_hash_params, write)
    ensures acc(res.num_hash_functions, write) && acc(res.num_ngrams, write)
    ensures acc(res.seed, write) && acc(res.allocator, write)
    ensures |res.ngram_weights| == num_ngrams
    ensures |res.lsh_hash_params| == num_hash_funcs * 2
  {
    var weights: Seq[Real] := allocator.alloc_f32(num_ngrams);
    var i: Int := 0;
    while (i < |weights|)
      invariant 0 <= i && i <= |weights|
      invariant |weights| == num_ngrams
    {
      var decay: Real := 1.0 / (i + 1);
      weights := weights[i := decay];
      i := i + 1;
    }

    var hash_params: Seq[Int] := allocator.alloc_u64(num_hash_funcs * 2);
    i := 0;
    while (i < num_hash_funcs)
      invariant 0 <= i && i <= num_hash_funcs
      invariant |hash_params| == num_hash_funcs * 2
    {
      var i_u64: Int := i;
      var i_plus_one: Int := i + 1;
      var a_val: Int := Bitwise.wrap_add(seed, Bitwise.wrap_mul(i_u64, 0x9e3779b97f4a7c15));
      var b_val: Int := Bitwise.wrap_add(seed, Bitwise.wrap_mul(i_plus_one, 0x517cc1b727220a95));
      hash_params := hash_params[i * 2 := a_val];
      hash_params := hash_params[i * 2 + 1 := b_val];
      i := i + 1;
    }

    new(res);
    res.ngram_weights := weights;
    res.lsh_hash_params := hash_params;
    res.num_hash_functions := num_hash_funcs;
    res.num_ngrams := num_ngrams;
    res.seed := seed;
    res.allocator := allocator;
  }

  method deinit()
    requires acc(this.ngram_weights, write)
    requires acc(this.lsh_hash_params, write)
    requires acc(this.allocator, write)
    ensures true
  {
    this.allocator.free_seq_real(this.ngram_weights);
    this.allocator.free_seq_int(this.lsh_hash_params);
    this.ngram_weights := Seq[Real] {};
    this.lsh_hash_params := Seq[Int] {};
  }

  method scoreSequence(tokens: Seq[Int], ssi: SSI) returns (raw_score: Real)
    requires acc(this.ngram_weights, read)
    requires acc(this.seed, read)
    requires acc(this.num_ngrams, read)
    requires acc(ssi.segments, read)
    ensures raw_score >= 0.0 && raw_score <= 1.0
  {
    if (|tokens| == 0) { raw_score := 0.0; return; }

    var ngram_score: Real := 0.0;
    var gram: Int := 1;
    while (gram < Min(this.num_ngrams, |tokens| + 1))
      invariant 1 <= gram
      invariant ngram_score >= 0.0
    {
      if (|tokens| >= gram) {
        var start: Int := 0;
        while (start < |tokens| - gram + 1)
          invariant 0 <= start
          invariant ngram_score >= 0.0
        {
          var ngram: Seq[Int] := tokens[start .. start + gram];
          var h: Int := Hashing.stable_hash(ngram, this.seed);
          var seg_opt: RankedSegment := null;
          seg_opt := ssi.getSegment(h);
          if (seg_opt != null) {
            var weight_idx: Int := Min(gram - 1, |this.ngram_weights| - 1);
            ngram_score := ngram_score + this.ngram_weights[weight_idx] * seg_opt.score;
          }
          start := start + 1;
        }
      }
      gram := gram + 1;
    }

    var diversity_score: Real := this.computeTokenDiversity(tokens);
    var proximity: Real := this.anchorProximity(tokens, ssi);

    var max_raw: Real := 100.0;
    var intermediate: Real := ngram_score + 0.3 * diversity_score + 0.3 * proximity;
    intermediate := FloatMath.clamp(intermediate, 0.0, max_raw);
    raw_score := intermediate / max_raw;
  }

  method scoreSequenceWithQuery(tokens: Seq[Int], query: Seq[Int], ssi: SSI) returns (final_score: Real)
    requires acc(this.ngram_weights, read)
    requires acc(this.seed, read)
    requires acc(this.num_ngrams, read)
    requires acc(ssi.segments, read)
    ensures final_score >= 0.0 && final_score <= 1.0
  {
    var base_score: Real := this.scoreSequence(tokens, ssi);
    var token_overlap: Real := this.computeTokenOverlap(tokens, query);
    var jaccard: Real := this.computeJaccardSimilarity(tokens, query);

    var combined: Real := base_score * 0.4 + token_overlap * 0.3 + jaccard * 0.3;
    final_score := FloatMath.clamp(combined, 0.0, 1.0);
  }

  method computeTokenDiversity(tokens: Seq[Int]) returns (diversity: Real)
    requires acc(this.allocator, write)
    ensures diversity >= 0.0 && diversity <= 1.0
  {
    if (|tokens| == 0) { diversity := 0.0; return; }

    var seen: Set[Int] := Set[Int] {};
    var i: Int := 0;
    while (i < |tokens|)
      invariant 0 <= i && i <= |tokens|
    {
      seen := seen ++ Set[Int] { tokens[i] };
      i := i + 1;
    }
    diversity := Real(|seen|) / Real(|tokens|);
  }

  method computeTokenOverlap(tokens: Seq[Int], query: Seq[Int]) returns (overlap_score: Real)
    ensures overlap_score >= 0.0 && overlap_score <= 1.0
  {
    if (|tokens| == 0 || |query| == 0) { overlap_score := 0.0; return; }

    var overlap: Int := 0;
    var i: Int := 0;
    while (i < |tokens|)
      invariant 0 <= i && i <= |tokens|
      invariant overlap >= 0
    {
      var j: Int := 0;
      while (j < |query|)
        invariant 0 <= j && j <= |query|
      {
        if (tokens[i] == query[j]) {
          overlap := overlap + 1;
          j := |query|;
        } else {
          j := j + 1;
        }
      }
      i := i + 1;
    }
    overlap_score := Real(overlap) / Real(Max(|tokens|, |query|));
  }

  method computeJaccardSimilarity(tokens: Seq[Int], query: Seq[Int]) returns (jaccard: Real)
    requires acc(this.allocator, write)
    ensures jaccard >= 0.0 && jaccard <= 1.0
  {
    if (|tokens| == 0 && |query| == 0) { jaccard := 1.0; return; }
    if (|tokens| == 0 || |query| == 0) { jaccard := 0.0; return; }

    var intersection: Int := 0;
    var union_size: Int := 0;
    var seen: Map[Int, Int] := Map[Int, Int] {};
    var i: Int := 0;
    while (i < |tokens|)
      invariant 0 <= i && i <= |tokens|
    {
      seen := seen[tokens[i] := 1];
      i := i + 1;
    }
    i := 0;
    while (i < |query|)
      invariant 0 <= i && i <= |query|
    {
      var val: Int;
      if (seen.hasKey(query[i])) {
        val := seen[query[i]];
      } else {
        val := 0;
      }
      if (val == 1) {
        seen := seen[query[i] := 2];
      } else {
        seen := seen[query[i] := 1];
      }
      i := i + 1;
    }

    i := 0;
    var keys: Seq[Int] := seen.dom_values();
    while (i < |keys|)
      invariant 0 <= i && i <= |keys|
      invariant intersection >= 0 && union_size >= 0
    {
      union_size := union_size + 1;
      if (seen[keys[i]] == 2) {
        intersection := intersection + 1;
      }
      i := i + 1;
    }

    if (union_size == 0) { jaccard := 0.0; return; }
    jaccard := Real(intersection) / Real(union_size);
  }

  method anchorProximity(tokens: Seq[Int], ssi: SSI) returns (proximity: Real)
    requires acc(ssi.segments, read)
    ensures proximity >= 0.0 && proximity <= 1.0
  {
    if (|tokens| == 0) { proximity := 0.0; return; }

    var anchors: Int := 0;
    var total_dist: Real := 0.0;
    var i: Int := 0;
    while (i < |tokens|)
      invariant 0 <= i && i <= |tokens|
      invariant total_dist >= 0.0
      invariant anchors >= 0
    {
      var seg: RankedSegment := ssi.getSegment(i);
      if (seg != null) {
        if (seg.anchor) {
          anchors := anchors + 1;
          var raw_dist: Int := Abs(i - seg.position);
          var dist: Real := Real(Min(raw_dist, 4294967295));
          total_dist := total_dist + dist;
        }
      }
      i := i + 1;
    }

    if (anchors == 0) { proximity := 0.0; return; }
    var denominator: Int := anchors * |tokens|;
    var denom_clamped: Int := Min(denominator, 4294967295);
    var denom_f32: Real := Real(Max(denom_clamped, 1));
    proximity := 1.0 - FloatMath.clamp(total_dist / denom_f32, 0.0, 1.0);
  }

  method rankCandidates(candidates: Seq[RankedSegment], ssi: SSI) returns (res_candidates: Seq[RankedSegment])
    requires acc(this.ngram_weights, read)
    requires acc(this.allocator, write)
    requires forall i: Int :: 0 <= i < |candidates| ==> acc(candidates[i].tokens, write) && acc(candidates[i].score, write) && acc(candidates[i].position, write) && acc(candidates[i].anchor, write)
    ensures forall i: Int :: 0 <= i < |res_candidates| ==> acc(res_candidates[i].tokens, write) && acc(res_candidates[i].score, write) && acc(res_candidates[i].position, write) && acc(res_candidates[i].anchor, write)
    ensures |res_candidates| == |candidates|
  {
    if (|candidates| == 0) { res_candidates := candidates; return; }

    var scores: Seq[Real] := this.allocator.alloc_f32(|candidates|);
    var i: Int := 0;
    while (i < |candidates|)
      invariant 0 <= i && i <= |candidates|
    {
      scores := scores[i := this.scoreSequence(candidates[i].tokens, ssi)];
      i := i + 1;
    }

    this.normalizeScoresStatic(scores);

    var indices: Seq[Int] := this.allocator.alloc_int(|candidates|);
    i := 0;
    while (i < |candidates|)
      invariant 0 <= i && i <= |candidates|
    {
      indices := indices[i := i];
      i := i + 1;
    }

    var sorted_indices: Seq[Int] := this.sortIndices(indices, scores);

    var new_candidates: Seq[RankedSegment] := Seq[RankedSegment]( |candidates|, null );
    i := 0;
    while (i < |candidates|)
      invariant 0 <= i && i <= |candidates|
    {
      var src_idx: Int := sorted_indices[i];
      var c: RankedSegment;
      new(c);
      c.init(this.allocator.dupe_u32(candidates[src_idx].tokens), scores[src_idx], candidates[src_idx].position, candidates[src_idx].anchor);
      new_candidates := new_candidates[i := c];
      i := i + 1;
    }

    res_candidates := new_candidates;
    this.allocator.free_seq_real(scores);
    this.allocator.free_seq_int(indices);
  }

  method sortIndices(indices: Seq[Int], scores: Seq[Real]) returns (sorted: Seq[Int])
    requires |indices| == |scores|
    ensures |sorted| == |indices|
  {
    sorted := indices;
  }

  method batchScore(sequences: Seq[Seq[Int]], ssi: SSI) returns (scores: Seq[Real])
    requires acc(this.ngram_weights, read)
    requires acc(this.allocator, write)
    ensures |scores| == |sequences|
  {
    if (|sequences| == 0) { scores := Seq[Real] {}; return; }
    scores := this.allocator.alloc_f32(|sequences|);
    var b: Int := 0;
    while (b < |sequences|)
      invariant 0 <= b && b <= |sequences|
    {
      scores := scores[b := this.scoreSequence(sequences[b], ssi)];
      b := b + 1;
    }
  }

  method topKHeap(ssi: SSI, query: Seq[Int], k: Int) returns (res: Seq[RankedSegment])
    requires acc(this.ngram_weights, read)
    requires acc(this.allocator, write)
    requires k > 0
    ensures |res| >= 0
  {
    var candidates: Seq[RankedSegment] := ssi.retrieveTopK(query, 1000);
    var heap: Seq[RankedSegment] := Seq[RankedSegment] {};
    var heap_size: Int := 0;

    var i: Int := 0;
    while (i < |candidates|)
      invariant 0 <= i && i <= |candidates|
      invariant heap_size <= k
    {
      var cand: RankedSegment := candidates[i];
      var score: Real := this.scoreSequenceWithQuery(cand.tokens, query, ssi);

      if (!FloatMath.is_nan(score) && !FloatMath.is_inf(score)) {
        if (heap_size < k) {
          var r: RankedSegment;
          new(r);
          r.init(cand.tokens, score, cand.position, cand.anchor);
          heap := heap + Seq[RankedSegment] { r };
          heap_size := heap_size + 1;
        } else {
          var min_idx: Int := 0;
          var min_s: Real := heap[0].score;
          var j: Int := 1;
          while (j < heap_size)
            invariant 0 <= j && j <= heap_size
          {
            if (heap[j].score < min_s) {
              min_s := heap[j].score;
              min_idx := j;
            }
            j := j + 1;
          }
          if (score > min_s) {
            heap := heap[min_idx := heap[heap_size - 1]];
            heap_size := heap_size - 1;
            var r: RankedSegment;
            new(r);
            r.init(cand.tokens, score, cand.position, cand.anchor);
            heap := heap + Seq[RankedSegment] { r };
            heap_size := heap_size + 1;
          }
        }
      }
      i := i + 1;
    }

    res := heap;
  }

  method updateWeights(gradients: Seq[Real])
    requires acc(this.ngram_weights, write)
    ensures true
  {
    var i: Int := 0;
    while (i < Min(|this.ngram_weights|, |gradients|))
      invariant 0 <= i && i <= Min(|this.ngram_weights|, |gradients|)
    {
      var grad: Real := gradients[i];
      if (!FloatMath.is_nan(grad) && !FloatMath.is_inf(grad)) {
        this.ngram_weights := this.ngram_weights[i := FloatMath.clamp(this.ngram_weights[i] + grad * 0.01, 0.0, 1.0)];
      }
      i := i + 1;
    }
  }

  method minHashSignature(tokens: Seq[Int]) returns (sig: Seq[Int])
    requires acc(this.lsh_hash_params, read)
    requires acc(this.num_hash_functions, read)
    requires acc(this.allocator, write)
    ensures |sig| == this.num_hash_functions
  {
    if (|tokens| == 0) {
      sig := this.allocator.alloc_u64(this.num_hash_functions);
      var i: Int := 0;
      while (i < |sig|)
        invariant 0 <= i && i <= |sig|
      {
        sig := sig[i := 18446744073709551615];
        i := i + 1;
      }
      return;
    }

    sig := this.allocator.alloc_u64(this.num_hash_functions);
    var h: Int := 0;
    while (h < this.num_hash_functions)
      invariant 0 <= h && h <= this.num_hash_functions
    {
      var min_hash: Int := 18446744073709551615;
      var seed_a: Int := this.lsh_hash_params[h * 2];
      var seed_b: Int := this.lsh_hash_params[h * 2 + 1];

      var t: Int := 0;
      while (t < |tokens|)
        invariant 0 <= t && t <= |tokens|
      {
        var hash_val: Int := Bitwise.xor(Hashing.stable_hash(Seq[Int] { tokens[t] }, seed_a), seed_b);
        if (hash_val < min_hash) {
          min_hash := hash_val;
        }
        t := t + 1;
      }
      sig := sig[h := min_hash];
      h := h + 1;
    }
  }

  method jaccardSimilarityFromSignatures(sig1: Seq[Int], sig2: Seq[Int]) returns (sim: Real)
    ensures sim >= 0.0 && sim <= 1.0
  {
    if (|sig1| != |sig2|) { sim := 0.0; return; }
    if (|sig1| == 0) { sim := 0.0; return; }

    var matches: Int := 0;
    var i: Int := 0;
    while (i < |sig1|)
      invariant 0 <= i && i <= |sig1|
    {
      if (sig1[i] == sig2[i]) { matches := matches + 1; }
      i := i + 1;
    }
    sim := Real(matches) / Real(|sig1|);
  }

  method estimateJaccard(set1: BitSet, set2: BitSet) returns (est: Real)
    requires acc(set1.bits, read) && acc(set2.bits, read)
    ensures est >= 0.0 && est <= 1.0
  {
    var intersect: Int := 0;
    var union_count: Int := 0;
    var words: Int := Min(|set1.bits|, |set2.bits|);
    var i: Int := 0;
    while (i < words)
      invariant 0 <= i && i <= words
    {
      intersect := intersect + Bitwise.popcount(Bitwise.and(set1.bits[i], set2.bits[i]));
      union_count := union_count + Bitwise.popcount(Bitwise.or(set1.bits[i], set2.bits[i]));
      i := i + 1;
    }
    if (union_count == 0) { est := 0.0; return; }
    est := Real(intersect) / Real(union_count);
  }

  method vectorScore(embedding: Tensor, query_emb: Tensor) returns (score: Real)
    requires acc(embedding.data, read) && acc(embedding.shape, read)
    requires acc(query_emb.data, read) && acc(query_emb.shape, read)
    ensures score >= -1.0 && score <= 1.0
  {
    if (|embedding.data| == 0) { score := 0.0; return; }

    var dot_prod: Real := 0.0;
    var norm_emb: Real := 0.0;
    var norm_query: Real := 0.0;

    var len: Int := |embedding.data|;
    var i: Int := 0;
    while (i < len)
      invariant 0 <= i && i <= len
    {
      var e: Real := embedding.data[i];
      var q: Real := query_emb.data[i];

      if (!FloatMath.is_nan(e) && !FloatMath.is_nan(q) && !FloatMath.is_inf(e) && !FloatMath.is_inf(q)) {
        dot_prod := dot_prod + e * q;
        norm_emb := norm_emb + e * e;
        norm_query := norm_query + q * q;
      }
      i := i + 1;
    }

    if (norm_emb <= 0.0 || norm_query <= 0.0) { score := 0.0; return; }
    norm_emb := FloatMath.sqrt(norm_emb);
    norm_query := FloatMath.sqrt(norm_query);

    if (norm_emb == 0.0 || norm_query == 0.0) { score := 0.0; return; }

    score := FloatMath.clamp(dot_prod / (norm_emb * norm_query), -1.0, 1.0);
  }

  method dotProductScore(embedding: Tensor, query_emb: Tensor) returns (score: Real)
    requires acc(embedding.data, read)
    requires acc(query_emb.data, read)
  {
    if (|embedding.data| == 0) { score := 0.0; return; }

    var dot_prod: Real := 0.0;
    var len: Int := |embedding.data|;
    var i: Int := 0;
    while (i < len)
      invariant 0 <= i && i <= len
    {
      var e: Real := embedding.data[i];
      var q: Real := query_emb.data[i];
      if (!FloatMath.is_nan(e) && !FloatMath.is_nan(q) && !FloatMath.is_inf(e) && !FloatMath.is_inf(q)) {
        dot_prod := dot_prod + e * q;
      }
      i := i + 1;
    }
    score := dot_prod;
  }

  method weightedAverage(scores: Seq[Real], weights: Seq[Real]) returns (avg: Real)
    requires |scores| == |weights|
    ensures true
  {
    if (|scores| == 0) { avg := 0.0; return; }

    var num: Real := 0.0;
    var den: Real := 0.0;
    var i: Int := 0;
    while (i < |scores|)
      invariant 0 <= i && i <= |scores|
    {
      var s: Real := scores[i];
      var w: Real := weights[i];
      if (!FloatMath.is_nan(s) && !FloatMath.is_nan(w) && !FloatMath.is_inf(s) && !FloatMath.is_inf(w)) {
        num := num + s * w;
        den := den + w;
      }
      i := i + 1;
    }
    if (den == 0.0) { avg := 0.0; return; }
    avg := num / den;
  }

  method exponentialDecay(scores: Seq[Real], decay_factor: Real)
    requires acc(scores, write)
    ensures true
  {
    if (|scores| == 0) { return; }
    if (decay_factor <= 0.0 || decay_factor >= 1.0) { return; }

    var current_decay: Real := 1.0;
    var i: Int := 0;
    while (i < |scores|)
      invariant 0 <= i && i <= |scores|
    {
      if (!FloatMath.is_nan(scores[i]) && !FloatMath.is_inf(scores[i])) {
        scores := scores[i := scores[i] * current_decay];
      }
      current_decay := current_decay * decay_factor;
      i := i + 1;
    }
  }

  method normalizeScores(scores: Seq[Real])
    requires acc(scores, write)
    ensures true
  {
    this.normalizeScoresStatic(scores);
  }

  method normalizeScoresStatic(scores: Seq[Real])
    requires acc(scores, write)
    ensures true
  {
    if (|scores| == 0) { return; }

    var min_score: Real := FloatMath.inf_val();
    var max_score: Real := -FloatMath.inf_val();
    var valid_count: Int := 0;

    var i: Int := 0;
    while (i < |scores|)
      invariant 0 <= i && i <= |scores|
    {
      var s: Real := scores[i];
      if (!FloatMath.is_nan(s) && !FloatMath.is_inf(s)) {
        valid_count := valid_count + 1;
        if (s < min_score) { min_score := s; }
        if (s > max_score) { max_score := s; }
      }
      i := i + 1;
    }

    if (valid_count == 0) { return; }
    if (max_score == min_score) {
      i := 0;
      while (i < |scores|)
        invariant 0 <= i && i <= |scores|
      {
        if (!FloatMath.is_nan(scores[i]) && !FloatMath.is_inf(scores[i])) {
          scores := scores[i := 0.5];
        }
        i := i + 1;
      }
      return;
    }

    var range: Real := max_score - min_score;
    i := 0;
    while (i < |scores|)
      invariant 0 <= i && i <= |scores|
    {
      if (!FloatMath.is_nan(scores[i]) && !FloatMath.is_inf(scores[i])) {
        scores := scores[i := (scores[i] - min_score) / range];
      }
      i := i + 1;
    }
  }

  method rankByMultipleCriteria(candidates: Seq[RankedSegment], criteria: Seq[Seq[Real]], weights: Seq[Real]) returns (res_candidates: Seq[RankedSegment])
    requires acc(this.allocator, write)
    requires forall i: Int :: 0 <= i < |candidates| ==> acc(candidates[i].tokens, write) && acc(candidates[i].score, write) && acc(candidates[i].position, write) && acc(candidates[i].anchor, write)
    ensures forall i: Int :: 0 <= i < |res_candidates| ==> acc(res_candidates[i].tokens, write) && acc(res_candidates[i].score, write) && acc(res_candidates[i].position, write) && acc(res_candidates[i].anchor, write)
  {
    if (|candidates| == 0) { res_candidates := candidates; return; }
    if (|criteria| == 0) { res_candidates := candidates; return; }
    if (|weights| == 0) { res_candidates := candidates; return; }

    var num_cand: Int := |candidates|;
    var num_crit: Int := Min(|criteria|, |weights|);

    var combined: Seq[Real] := this.allocator.alloc_f32(num_cand);
    var c: Int := 0;
    while (c < num_cand)
      invariant 0 <= c && c <= num_cand
    {
      var crit_score: Real := 0.0;
      var cr: Int := 0;
      while (cr < num_crit)
        invariant 0 <= cr && cr <= num_crit
      {
        if (c < |criteria[cr]|) {
          var score_val: Real := criteria[cr][c];
          var weight_val: Real := weights[cr];
          if (!FloatMath.is_nan(score_val) && !FloatMath.is_nan(weight_val) && !FloatMath.is_inf(score_val) && !FloatMath.is_inf(weight_val)) {
            crit_score := crit_score + score_val * weight_val;
          }
        }
        cr := cr + 1;
      }
      combined := combined[c := crit_score];
      c := c + 1;
    }

    var indices: Seq[Int] := this.allocator.alloc_int(num_cand);
    var i: Int := 0;
    while (i < num_cand)
      invariant 0 <= i && i <= num_cand
    {
      indices := indices[i := i];
      i := i + 1;
    }

    var sorted_indices: Seq[Int] := this.sortIndices(indices, combined);

    var new_candidates: Seq[RankedSegment] := Seq[RankedSegment]( num_cand, null );
    i := 0;
    while (i < num_cand)
      invariant 0 <= i && i <= num_cand
    {
      var src_idx: Int := sorted_indices[i];
      var rc: RankedSegment;
      new(rc);
      rc.init(this.allocator.dupe_u32(candidates[src_idx].tokens), combined[src_idx], candidates[src_idx].position, candidates[src_idx].anchor);
      new_candidates := new_candidates[i := rc];
      i := i + 1;
    }

    res_candidates := new_candidates;
    this.allocator.free_seq_real(combined);
    this.allocator.free_seq_int(indices);
  }

  method streamingRank(reader: Reader, ssi: SSI, k: Int) returns (res: Seq[RankedSegment])
    requires acc(this.ngram_weights, read)
    requires acc(this.allocator, write)
    requires acc(reader.data, read)
    requires acc(reader.pos, write)
    ensures |res| >= 0
  {
    if (k == 0) { res := Seq[RankedSegment] {}; return; }

    var top_k_list: Seq[RankedSegment] := Seq[RankedSegment] {};
    var position: Int := 0;

    while (true)
      invariant position >= 0
      invariant |top_k_list| <= k
    {
      var bytes: Seq[Int] := reader.read(1024);
      if (|bytes| == 0) { break; }

      var score: Real := this.scoreSequence(bytes, ssi);
      if (!FloatMath.is_nan(score) && !FloatMath.is_inf(score)) {
        if (|top_k_list| < k) {
          var seg: RankedSegment;
          new(seg);
          seg.init(bytes, score, position, false);
          top_k_list := top_k_list + Seq[RankedSegment] { seg };
        } else {
          var min_idx: Int := 0;
          var min_score: Real := top_k_list[0].score;
          var j: Int := 1;
          while (j < |top_k_list|)
            invariant 0 <= j && j <= |top_k_list|
          {
            if (top_k_list[j].score < min_score) {
              min_score := top_k_list[j].score;
              min_idx := j;
            }
            j := j + 1;
          }
          if (score > min_score) {
            top_k_list := top_k_list[min_idx := top_k_list[|top_k_list| - 1]];
            var seg: RankedSegment;
            new(seg);
            seg.init(bytes, score, position, false);
            top_k_list := top_k_list + Seq[RankedSegment] { seg };
            top_k_list := top_k_list[.. |top_k_list| - 1];
          }
        }
      }
      position := position + 1;
    }
    res := top_k_list;
  }

  method parallelScore(sequences: Seq[Seq[Int]], ssi: SSI) returns (scores: Seq[Real])
    requires acc(this.ngram_weights, read)
    requires acc(this.allocator, write)
    ensures |scores| == |sequences|
  {
    if (|sequences| == 0) { scores := Seq[Real] {}; return; }
    scores := this.allocator.alloc_f32(|sequences|);
    var i: Int := 0;
    while (i < |sequences|)
      invariant 0 <= i && i <= |sequences|
    {
      scores := scores[i := this.scoreSequence(sequences[i], ssi)];
      i := i + 1;
    }
  }

  method calibrateWeights(training_data: Seq[Seq[Int]], labels: Seq[Real], ssi: SSI, epochs: Int)
    requires acc(this.ngram_weights, write)
    requires acc(this.allocator, write)
    ensures true
  {
    if (|training_data| == 0 || |labels| == 0) { return; }
    if (|training_data| != |labels|) { return; }

    var gradients: Seq[Real] := this.allocator.alloc_f32(|this.ngram_weights|);
    var epoch: Int := 0;
    while (epoch < epochs)
      invariant 0 <= epoch && epoch <= epochs
    {
      var i: Int := 0;
      while (i < |gradients|)
        invariant 0 <= i && i <= |gradients|
      {
        gradients := gradients[i := 0.0];
        i := i + 1;
      }

      i := 0;
      while (i < |training_data|)
        invariant 0 <= i && i <= |training_data|
      {
        var pred: Real := this.scoreSequence(training_data[i], ssi);
        var label: Real := labels[i];

        if (!FloatMath.is_nan(pred) && !FloatMath.is_nan(label) && !FloatMath.is_inf(pred) && !FloatMath.is_inf(label)) {
          var err: Real := pred - label;
          var g: Int := 0;
          while (g < |this.ngram_weights|)
            invariant 0 <= g && g <= |this.ngram_weights|
          {
            gradients := gradients[g := gradients[g] + err * 0.01];
            g := g + 1;
          }
        }
        i := i + 1;
      }
      this.updateWeights(gradients);
      epoch := epoch + 1;
    }
    this.allocator.free_seq_real(gradients);
  }
}

