  requires true
  ensures a <= b ==> result == a
  ensures a > b ==> result == b
{
  if (a <= b) { a } else { b }
}

function Max(a: Int, b: Int): Int
  requires true
  ensures a >= b ==> result == a
  ensures a < b ==> result == b
{
  if (a >= b) { a } else { b }
}

function Abs(a: Int): Int
  requires true
  ensures result >= 0
{
