domain Bitwise {
  function wrap_add(a: Int, b: Int): Int
  function wrap_mul(a: Int, b: Int): Int
  function xor(a: Int, b: Int): Int
  function and(a: Int, b: Int): Int
  function or(a: Int, b: Int): Int
  function popcount(a: Int): Int
  function lsh(a: Int, b: Int): Int

  axiom wrap_add_axiom {
    forall a: Int, b: Int :: { wrap_add(a, b) }
      wrap_add(a, b) == (a + b) % (2^64)
  }
  axiom wrap_mul_axiom {
    forall a: Int, b: Int :: { wrap_mul(a, b) }
      wrap_mul(a, b) == (a * b) % (2^64)
  }
  axiom xor_axiom {
    forall a: Int, b: Int :: { xor(a, b) }
      xor(a, b) >= 0
  }
  axiom popcount_axiom {
    forall a: Int :: { popcount(a) }
      popcount(a) >= 0 && popcount(a) <= 64
  }
}

domain FloatMath {
  function clamp(val: Real, min_val: Real, max_val: Real): Real
  function sqrt(val: Real): Real
  function is_nan(val: Real): Bool
  function is_inf(val: Real): Bool
  function inf_val(): Real

  axiom clamp_axiom {
    forall val: Real, min_val: Real, max_val: Real :: { clamp(val, min_val, max_val) }
      min_val <= max_val ==>
      (val < min_val ==> clamp(val, min_val, max_val) == min_val) &&
      (val > max_val ==> clamp(val, min_val, max_val) == max_val) &&
      (min_val <= val && val <= max_val ==> clamp(val, min_val, max_val) == val)
  }
  axiom sqrt_axiom {
    forall val: Real :: { sqrt(val) }
      val >= 0.0 ==> sqrt(val) >= 0.0 && sqrt(val) * sqrt(val) == val
  }
  axiom nan_inf_axiom {
    forall val: Real :: { is_nan(val), is_inf(val) }
      is_nan(val) ==> !is_inf(val)
  }
}

domain Hashing {
  function stable_hash(data: Seq[Int], seed: Int): Int
  axiom stable_hash_range {
    forall data: Seq[Int], seed: Int :: { stable_hash(data, seed) }
      stable_hash(data, seed) >= 0
  }
}

class RankedSegment {
  var tokens: Seq[Int]
  var score: Real
  var position: Int
  var anchor: Bool

  method init(toks: Seq[Int], sc: Real, pos: Int, anc: Bool)
    modifies this.tokens, this.score, this.position, this.anchor
    ensures acc(this.tokens, write) && acc(this.score, write) && acc(this.position, write) && acc(this.anchor, write)
    ensures this.tokens == toks && this.score == sc && this.position == pos && this.anchor == anc
  {
    this.tokens := toks;
    this.score := sc;
    this.position := pos;
    this.anchor := anc;
  }

  method deinit()
    requires acc(this.tokens, write)
    ensures true
  {
    this.tokens := Seq[Int] {};
  }
}

class BitSet {
  var bits: Seq[Int]

  method init(cap: Int)
    modifies this.bits
    ensures acc(this.bits, write) && |this.bits| == (cap / 64 + 1)
  {
    this.bits := Seq[Int] { 0, 0, 0 };
  }

  method set(index: Int)
    requires acc(this.bits, write)
    requires 0 <= index < |this.bits| * 64
    modifies this.bits
  {
    var word_idx: Int := index / 64;
    var bit_idx: Int := index % 64;
    var mask: Int := Bitwise.lsh(1, bit_idx);
    this.bits := this.bits[word_idx := Bitwise.or(this.bits[word_idx], mask)];
  }

  method deinit()
    requires acc(this.bits, write)
    ensures true
  {
    this.bits := Seq[Int] {};
  }
}

class Tensor {
  var data: Seq[Real]
  var shape: Seq[Int]

  method init(dims: Seq[Int])
    modifies this.data, this.shape
    ensures acc(this.data, write) && acc(this.shape, write)
    ensures this.shape == dims
    ensures |this.data| > 0
  {
    this.shape := dims;
    this.data := Seq[Real] { 0.0, 0.0, 0.0 };
  }

  method deinit()
    requires acc(this.data, write) && acc(this.shape, write)
    ensures true
  {
    this.data := Seq[Real] {};
    this.shape := Seq[Int] {};
  }
}

class SSI {
  var segments: Seq[RankedSegment]

  method init()
    modifies this.segments
    ensures acc(this.segments, write) && |this.segments| == 0
  {
    this.segments := Seq[RankedSegment] {};
  }

  method addSequence(toks: Seq[Int], pos: Int, anc: Bool)
    requires acc(this.segments, write)
    modifies this.segments
    ensures acc(this.segments, write)
  {
    var seg: RankedSegment;
    new(seg);
    seg.init(toks, 0.0, pos, anc);
    this.segments := this.segments + Seq[RankedSegment] { seg };
  }

  method deinit()
    requires acc(this.segments, write)
    ensures true
  {
  }

  method getSegment(h: Int) returns (s: RankedSegment)
    requires acc(this.segments, read)
    ensures s == null || (acc(s.tokens, read) && acc(s.score, read) && acc(s.position, read) && acc(s.anchor, read))
  {
    if (|this.segments| > 0) {
      s := this.segments[0];
    } else {
      s := null;
    }
  }

  method retrieveTopK(query: Seq[Int], k: Int) returns (candidates: Seq[RankedSegment])
    requires acc(this.segments, read)
    ensures |candidates| >= 0
  {
    candidates := Seq[RankedSegment] {};
  }
}

class Allocator {
  var dummy: Int

  method init()
    ensures acc(this.dummy, write)
  {
    this.dummy := 0;
  }

  method alloc_f32(len: Int) returns (res: Seq[Real])
    requires len >= 0
    ensures |res| == len
  {
