  }

  method free_seq_int(s: Seq[Int])
  requires true
  {
  }

  method free_seq_real(s: Seq[Real])
  requires true
  {
  }

  method free_seq_bool(s: Seq[Bool])
  requires true
  {
  }

  method free_seq_seq_int(s: Seq[Seq[Int]])
  requires true
  {
  }

  method dupe_u32(src: Seq[Int]) returns (res: Seq[Int])
  ensures |res| == |src|
